window.NPC_CHUNK_18 = [{"name":"Derghodaemon","cr":12,"xp":19200,"race":"Derghodaemon","age_category":"Adult","alignment":"NE","size":"Large","type":"outsider","sub_types":["daemon","evil","extraplanar"],"init":5,"senses":["all-around vision","darkvision 60 ft.","detect magic","see invisibility"],"auras":["feeblemind (DC 20)"],"ac":27,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+5 Dex, +13 natural, -1 size","hp":161,"hd":"14d10+84","hd_value":14,"fort":15,"ref":14,"will":7,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":["cold 10","electricity 10","fire 10"],"sr":23,"speed":[{"type":"land","speed":40}],"melee":"5 claws +21 (1d6+8/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+12 plus 2 Constitution damage"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"creeping doom"},{"spell":"insect plague"},{"spell":"summon daemon","details":"1 derghodaemon 30%, level 4"}]},{"frequency":"3/day","spells":[{"spell":"fear"},{"spell":"quickened summon swarm"}]}],"strength":27,"dexterity":20,"constitution":22,"intelligence":7,"wisdom":17,"charisma":16,"baseatk":14,"cmb":23,"cmd":38,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Improved Critical (claws)"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (summon swarm)"},{"feat":"Sickening Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":20},{"skill":"Perception","value":28},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":18}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"sq":["swarmwalking"],"special_abilities":[{"type":"All-Around Vision","kind":"Ex","details":"A derghodaemon's multiple eyes grant it a +8 racial bonus on Perception checks. It cannot be flanked."},{"type":"Feeblemind Aura","kind":"Su","details":"By grinding and clicking its mandibles and chitinous plates together (a free action), a derghodaemon can affect all creatures within 30 ft. as if by a feeblemind spell. Daemons are immune to this effect, but all other creatures must make a DC 20 Will save to resist the effects. A subject that succumbs to this effect remains affected by it as long as the derghodaemon continues to maintain the aura and the subject remains within 30 ft. of the derghodaemon. Once either condition ends, a victim of this effect can attempt a new DC 20 Will save once per hour to recover from the effect; otherwise, it can be cured by a heal, limited wish, miracle, or wish spell. A derghodaemon cannot use its spelllike abilities or its gnaw attack in any round in which it uses its feeblemind aura. This is a sonic mind-affecting effect. The save DC is Charisma-based."},{"type":"Swarmwalking","kind":"Su","details":"A derghodaemon is immune to damage or distraction effects caused by swarms."}],"during_combat":"The derghodaemon attempts to summon another of its kind on the first round of combat and then casts insect plague and creeping doom on the following rounds, supplementing its swarm creation each round with quickened summon swarm attacks. It changes to melee attacks if surrounded.","morale":"The derghodaemon fights to the death.","source":"AP 34, Tome of Horrors Revised 80"},{"name":"Bloody Skeletal Champion","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":6}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"bloody@skeletal champion","init":7,"senses":["darkvision 60 ft."],"ac":22,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+6 armor, +3 Dex, +2 natural, +1 shield","hp":72,"hd":"2d8+6d10+30","hd_value":8,"hp_mods":"fast healing 4","fort":7,"ref":5,"will":4,"defensive_abilities":["channel resistance +4"],"dr":"5/bludgeoning","immunities":["cold","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"+1 greatsword +12 (2d6+12/19-20)","ranged":"+1 composite longbow +10 (1d8+11/x3)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":17,"intelligence":10,"wisdom":8,"charisma":14,"baseatk":7,"cmb":11,"cmd":24,"feats":[{"feat":"Deadly Aim"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (composite longbow)"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (composite longbow)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Intimidate","value":13},{"skill":"Perception","value":10},{"skill":"Ride","value":7},{"skill":"Stealth","value":11}],"languages":["Common"],"sq":["armor training 1","weapon training (heavy blades +1)"],"special_abilities":[{"type":"Deathless","kind":"Su","details":"A bloody skeletal champion is destroyed when reduced to 0 hit points, but it returns to life 1 hour later at 1 hit point, allowing its fast healing to resume healing it thereafter. A bloody skeletal champion can be permanently destroyed if it is destroyed by positive energy, if it is reduced to 0 hit points in the area of a bless or hallow spell, or if its remains are sprinkled with a vial of holy water. Destroying the runes inscribed on the wall at area D5 removes the deathless quality from these undead."}],"gear":"breastplate, +1 greatsword, +1 composite longbow (+4 Str) with 20 arrows","during_combat":"These bloody skeletal champions open combat with their bows and then split into two groups as the PCs approach, allowing at least half their number to hang back and continue firing arrows while the others engage in melee. They always use Deadly Aim and Power Attack when attacking (their statistics above reflect this tactic).","morale":"These undead fight until destroyed.","source":"AP 34, Pathfinder RPG Bestiary 250-252"},{"name":"Zorek","cr":12,"xp":12800,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of gorum","level":12}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["chaotic","human"],"templates_applied":"divine guardian","init":4,"ac":21,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+7 armor, +4 deflection, -1 Dex, +2 natural, -1 size","hp":150,"hd":"12d8+96","hd_value":12,"hp_mods":"fast healing 5","fort":16,"ref":3,"will":13,"defensive_abilities":["ability healing"],"dr":"5/ evil","immunities":["disease","mind-affecting effects","poison"],"weaknesses":["bound to the faith"],"speed":[{"type":"land","speed":60}],"melee":"+3 anarchic spear +19 (2d6+13/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"6d6, DC 19, 6/day"},{"type":"might of the gods","details":"+12, 12 rounds/day"},{"type":"weapon master","details":"12 rounds/day"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"battle rage","details":"+6 damage"},{"spell":"strength surge","details":"+6"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":12,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"antilife shell"},{"spell":"blade barrier","type":"domain"},{"spell":"heal"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"flame strike"},{"spell":"greater command"},{"spell":"righteous might","type":"domain"},{"spell":"wall of stone"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"air walk"},{"spell":"chaos hammer"},{"spell":"divine power","type":"domain"},{"spell":"freedom of movement"},{"spell":"greater magic weapon"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic","count":2},{"spell":"invisibility purge"},{"spell":"magic vestment","type":"domain"},{"spell":"searing light"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"bull's strength","type":"domain"},{"spell":"hold person"},{"spell":"resist energy"},{"spell":"sound burst"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"divine favor"},{"spell":"enlarge person","type":"domain"},{"spell":"obscuring mist"},{"spell":"protection from law"},{"spell":"sanctuary"},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"light"},{"spell":"mending"},{"spell":"stabilize"}]}],"spelldomains":"Strength","strength":24,"dexterity":8,"constitution":23,"intelligence":8,"wisdom":20,"charisma":16,"baseatk":9,"cmb":17,"cmd":30,"feats":[{"feat":"Combat Casting"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (spear)"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (spear)"}],"skills":[{"skill":"Knowledge (religion)","value":14},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":0},{"skill":"Survival","value":11}],"languages":["Hallit"],"sq":["blessed life","sacred site"],"special_abilities":[{"type":"Ability Healing","kind":"Ex","details":"As a divine guardian, Zorek heals 1 point of ability damage per round in each damaged ability score."},{"type":"Blessed Life","kind":"Ex","details":"Zorek doesn't age or breathe, and he doesn't need to eat, drink, or sleep."},{"type":"Bound to the Faith","kind":"Ex","details":"A worshiper of Gorum with the Command Undead or Turn Undead feat can use the effects of these feats on Zorek as if he were an undead creature. Zorek suffers a -4 penalty on his Will save to negate the effect."},{"type":"Sacred Site","kind":"Ex","details":"Zorek is bound to guard Armag's Tomb by Gorum himself, and he cannot leave the tomb complex. Should Zorek ever leave the tomb, he immediately takes 6d6 points of Constitution drain as the years of lost food, drink, and sleep return tenfold."}],"gear":"+1 light fortification hide armor, +1 anarchic spear","before_combat":"Zorek casts magic vestment and greater magic weapon daily. His status as divine guardian allows him to track the PCs' movements through the tomb, and as they approach this chamber, he casts the following spells in this order: freedom of movement, air walk, bear's endurance, bull's strength, shield of faith, righteous might, and divine favor.","during_combat":"Zorek's first acts in combat are to cast antilife shell and to moves to the top of the stairs leading down to area D12. He then uses his ranged spells to soften up the PCs for 4 rounds (favoring blade barrier, his flame strikes, and chaos hammer) before negating his antilife shell by stepping up to engage the PCs in melee. Zorek casts heal on himself whenever he drops below 60 hit points.","morale":"Zorek fights to the death-if he's slain by mortals, he is granted the true freedom of death as certainly as if his charge to guard the tomb had been completed (although Zorek doesn't realize this).","source":"AP 34, Advanced Bestiary 60"},{"name":"Armag the Twice-Born","cr":13,"xp":25600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":5},{"class":"fighter","level":9}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+9 armor, +2 deflection, +2 Dex, +1 dodge, +2 natural, -2 rage","hp":204,"hd":"5d12+9d10+117","hd_value":14,"fort":16,"ref":6,"will":8,"save_mods":"+2 vs. fear","defensive_abilities":["bravery +2","improved uncanny dodge","trap sense +1"],"speed":[{"type":"land","speed":40}],"melee":"Ovinrbaane +24 (2d6+21/17-20 plus 1 bleed)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"18 rounds per day"},{"type":"rage powers","details":"no escape, rolling dodge +1"}],"strength":22,"dexterity":14,"constitution":22,"intelligence":8,"wisdom":10,"charisma":13,"baseatk":14,"cmb":20,"cmd":35,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Cleave"},{"feat":"Greater Weapon Focus (greatsword)"},{"feat":"Improved Critical (greatsword)"},{"feat":"Improved Iron Will"},{"feat":"Improved Vital Strike"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Intimidate","value":18},{"skill":"Perception","value":10},{"skill":"Survival","value":13},{"skill":"Swim","value":15}],"languages":["Hallit"],"sq":["armor training 2","weapon training (axes +2, heavy blades +1)"],"gear":"+3 breastplate with masterwork armor spikes, +2 keen battleaxe, Ovinrbaane, amulet of natural armor +2, belt of physical might +2 (Strength and Constitution), ring of protection +2, potions of cure serious wounds (3)","during_combat":"At the beginning of combat, Ovinrbaane casts aid on Armag and modifies his memory to make him believe that the PCs are his greatest enemies. He then rages and charges the strongest enemy in sight, using Improved Vital Strike and Power Attack-he continues using Power Attack throughout the battle. If surrounded by multiple foes, he uses Great Cleave. Against spellcasters, he counts on Ovinrbaane's dispel magic power to shield him from debilitating effects, preferring to take down a spellcaster's protectors before turning the blade on her.","morale":"Even before he succumbed to the bloodlust of Ovinrbaane, Armag never retreated or surrendered-he fights to the death.","source":"AP 34"},{"name":"Balenar Forsend","cr":2,"xp":600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":3}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":13,"ac_touch":13,"ac_flat_footed":10,"ac_mods":"+2 Dex, +1 dodge","hp":13,"hd":"3d8","hd_value":3,"fort":1,"ref":5,"will":2,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"unarmed strike +4 (1d3+1 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 17 rounds/day","details":"countersong, distraction, fascinate [DC 14], inspire competence +2, inspire courage +1"}],"spellsknown_caster_level":3,"spellsknown_concentration":6,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds"},{"spell":"expeditious retreat"},{"spell":"lesser confusion"},{"spell":"sleep"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"prestidigitation"},{"spell":"read magic"}]}],"strength":12,"dexterity":14,"constitution":10,"intelligence":13,"wisdom":8,"charisma":17,"baseatk":2,"cmb":3,"cmd":16,"feats":[{"feat":"Dodge"},{"feat":"Extra Performance"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Appraise","value":7},{"skill":"Bluff","value":9},{"skill":"Climb","value":7},{"skill":"Knowledge (local)","value":8},{"skill":"Perception","value":5},{"skill":"Perform (Act)","value":9},{"skill":"Perform (Oratory)","value":9},{"skill":"Stealth","value":8}],"languages":["Common","Draconic"],"sq":["bardic knowledge +1","versatile performance (oratory)"],"during_combat":"Balenar aids his rescuers in battle against the troglodytes, primarily using his spells and bardic performance. If his gear is returned to him, he will also join in combat as needed.","morale":"Though he's not interested in pointlessly sacrificing his life, Balenar will not abandon his rescuers.","source":"Master of the Fallen Fortress"},{"name":"Tasskar","cr":3,"xp":800,"race":"troglodyte","gender":"Male","age_category":"Adult","classes":[{"class":"druid","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["reptilian"],"init":5,"senses":["darkvision 90 ft."],"auras":["stench (30 ft., DC 13, 10 rounds)"],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+1 Dex, +6 natural","hp":32,"hd":"5d8+10","hd_value":5,"fort":9,"ref":3,"will":6,"speed":[{"type":"land","speed":30}],"melee":"mwk scimitar +6 (1d6+2/18-20), claw +0 (1d4), bite +0 (1d6) or flame blade +6 touch (1d8+1 fire), claw +0 (1d4), bite +0 (1d6) or 2 claws +5 (1d4+1), bite +5 (1d6+1)","ranged":"dart +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"flame blade"},{"spell":"summon swarm"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"magic fang"},{"spell":"obscuring mist"},{"spell":"produce flame"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"flare"},{"spell":"guidance"},{"spell":"resistance"},{"spell":"virtue"}]}],"strength":14,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":15,"charisma":9,"baseatk":3,"cmb":5,"cmd":16,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Climb","value":6},{"skill":"Handle Animal","value":7},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":8},{"skill":"Spellcraft","value":6},{"skill":"Stealth","value":8,"special":"+4 in rocky areas"},{"skill":"Survival","value":10}],"languages":["Draconic"],"sq":["nature bond (crocodile animal companion named Snapjaw)","nature sense","trackless step","wild empathy +2","woodland stride"],"gear":"darts (4), masterwork scimitar, cloak of resistance +1","before_combat":"If alerted to the presence of intruders, Tasskar casts magic fang on his crocodile before combat.","during_combat":"Tasskar summons a swarm of spiders with summon swarm and then casts produce flame to throw flames at opponents. He spontaneously casts summon nature's ally to summon a giant centipede if he feels he needs more allies in combat. If pressed into melee, Tasskar casts flame blade.","morale":"Tasskar is a fanatic and fights to the death.","source":"Master of the Fallen Fortress, Pathfinder RPG Bestiary 267"},{"name":"Damiel","cr":1,"xp":400,"race":"elf","gender":"Male","age_category":"Adult","classes":[{"class":"alchemist","level":1}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["elf"],"init":2,"senses":["low-light vision"],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":9,"hd":"1d8+1","hd_value":1,"fort":3,"ref":4,"will":-1,"immunities":["sleep"],"speed":[{"type":"land","speed":30}],"melee":"rapier +1 (1d6+1/18-20) or dagger +1 (1d4+1/19-20)","ranged":"sling +2 (1d4+1) or bomb +3 (1d6+3 fire) or thrown splash weapon +3 (by weapon +3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"4/day, 1d6+3 fire, DC 13"},{"type":"throw anything"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":1,"extractsprepared":[{"spell_level":1,"spells":[{"spell":"enlarge person"},{"spell":"true strike"}]}],"strength":12,"dexterity":15,"constitution":12,"intelligence":17,"wisdom":8,"charisma":10,"baseatk":0,"cmb":1,"cmd":13,"feats":[{"feat":"Brew Potion"},{"feat":"Skill Focus (Craft)","type":"alchemy"},{"feat":"Throw Anything"}],"skills":[{"skill":"Appraise","value":7},{"skill":"Climb","value":0},{"skill":"Craft (alchemy)","value":11},{"skill":"Disable Device","value":5},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":6},{"skill":"Spellcraft","value":7,"special":"+2 identify magic items"},{"skill":"Use Magic Device","value":4}],"languages":["Common","Draconic","Elven","Gnome","Goblin"],"sq":["alchemy","elven magic","extract","mutagen","weapon familiarity"],"special_abilities":[{"type":"Alchemy","kind":"Su","details":"You gain a +1 bonus when using Craft (alchemy) to create an alchemical item. You can use Craft (alchemy) to identify potions as if using detect magic; you must hold the potion for 1 round to make such a check."},{"type":"Bomb","kind":"Su","details":"A bomb is an explosive splash weapon created from raw ingredients and power from your innate magic. Creating and throwing a bomb is a standard action that provokes an attack of opportunity. Thrown bombs have a range of 20 ft. and use the \"Throw Splash Weapon\" special attack. Bombs are unstable, and if not used in the round they are created, they degrade and become inert. Splash damage from an alchemist bomb is always equal to the bomb's minimum damage (Reflex half )."},{"type":"Extract","kind":"Su","details":"An extract is a stored alchemist spell. You prepare your spells by mixing ingredients into a number of extracts, and then \"cast\" them by drinking the extract, like a potion. You can only create a certain number of extracts of each level per day (two 1st-level extracts at character level 1). When you mix an extract, you infuse the chemicals and reagents in the extract with magic siphoned from your own magical aura. An extract immediately becomes inert if it leaves your possession, reactivating as soon as it returns to your keeping; this means you cannot normally hand out your extracts for allies to use. An extract remains potent for 1 day before becoming inert, so you must re-prepare your extracts every day. Mixing an extract takes 1 minute of work-most alchemists prepare many extracts at the start of the day or just before going on an adventure, but you can keep some (or even all) of your daily extract slots open so you can prepare extracts in the field as needed. You \"cast\" an extract by drinking it, like drinking a potion. Your alchemist level is the caster level of the extract. The recipes for extracts you know are kept in your formula book."},{"type":"Mutagen","kind":"Su","details":"Mutagens are transformative elixirs that you can drink to enhance your physical abilities at the cost of your personality. It takes 1 hour to brew a dose of mutagen, and once brewed, it remains potent until used. You can only maintain one dose of mutagen at a time-if you brew a second dose, any existing mutagen becomes inert. A mutagen that isn't in your possession becomes inert until you pick it up again; non-alchemists cannot use mutagens. When you brew a mutagen, you select one physical ability score-either Strength, Dexterity, or Constitution. The mutagen gives you a +4 alchemical bonus to that ability score and a +2 natural armor bonus for 10 minutes, but you take a penalty to a mental ability score for that same amount of time (Strength mutagens give you an Intelligence penalty, Dexterity mutagens give you a Wisdom penalty, and Constitution mutagens give you a Charisma penalty). Drinking a mutagen is a standard action. Mutagens don't stack. Whenever you drink a mutagen, the effects of any previous mutagen immediately end."}],"gear":"studded leather armor, dagger, rapier, sling with 10 bullets, alchemist's kit (as spell component pouch), backpack, formula book (contains all prepared extracts, plus cure light wounds, expeditious retreat, and shield), rations (4), sunrods (3), thieves' tools, tindertwigs (6), various and sundry inebriants and intoxicants, 2 gp, potion of cure light wounds, potion of shield, acid, alchemist's fire (2), mutagen (Dexterity), oil flasks (5), tanglefoot bag, thunderstone","source":"Master of the Fallen Fortress"},{"name":"Alain","cr":1,"xp":400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cavalier","level":1}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 Dex, +2 shield","hp":12,"hd":"1d10+2","hd_value":1,"fort":4,"ref":1,"will":0,"speed":[{"type":"land","speed":30}],"melee":"longsword +5 (1d8+3/19-20) or lance +4 (1d8+3/x3) or flail +4 (1d8+3)","ranged":"light crossbow +2 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"challenge","details":"1/day, +1 damage, additional + 1 damage as long as only one threatening foe"}],"strength":17,"dexterity":13,"constitution":14,"intelligence":8,"wisdom":10,"charisma":12,"baseatk":1,"cmb":4,"cmd":15,"feats":[{"feat":"Mounted Combat"},{"feat":"Precise Strike"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Climb","value":3},{"skill":"Intimidate","value":5},{"skill":"Perception","value":4},{"skill":"Ride","value":5}],"languages":["Common"],"sq":["mount (horse named Donahan)","order of the cockatrice","tactician 1/day (Precise Strike)"],"special_abilities":[{"type":"Challenge","kind":"Ex","details":"Once per day, you can challenge a foe to combat. As a swift action, you choose one target within sight to challenge. Your melee attacks deal +1 extra damage whenever the attacks are made against the target of your challenge. You can use this ability once per day. Challenging a foe requires much of your concentration. After issuing a challenge you take a -2 penalty to your Armor Class, except against attacks made by the target of your challenge. The challenge remains in effect until the target is dead or unconscious or until the combat ends. Your challenge also includes another effect, which is listed in the Order of the Cockatrice section."},{"type":"Mount","kind":"Ex","details":"You gain the service of a loyal and trusty steed to carry you into battle. This mount functions as a druid's animal companion, using your cavalier level as your effective druid level. You don't take an armor check penalty on Ride checks while riding your mount. The mount is always considered combat trained and begins play with Light Armor Proficiency as a bonus feat. Your mount doesn't gain the share spells special ability of an animal companion. Your bond with your mount is strong, and you have learned to anticipate each other's moods and moves. Should your mount die, you may find another mount to serve you after 1 week of mourning. This new mount doesn't gain the link, evasion, devotion, or improved evasion special abilities until the next time you gain a level."},{"type":"Order","kind":"Ex","details":"At 1st level, you must pledge yourself to a specific order. The order grants you a number of bonuses, class skills, and special abilities. In addition, each order includes a number of edicts that you must follow. If you violate any of these edicts, you lose all benefits gained from your order for 24 hours. The violation of an edict is subject to GM interpretation."},{"type":"Tactician","kind":"Ex","details":"At 1st level, you receive a teamwork feat as a bonus feat (you have the Precise Strike feat). As a standard action, you can grant this feat to all allies within 30 ft. who can see and hear you. Allies retain the use of this bonus feat for 3 rounds. You can use this ability once per day."}],"gear":"chain shirt, heavy steel shield, light crossbow with 10 bolts, flail, lance, longsword, backpack, banner, bit and bridle, grappling hook, leather barding, rations (4), riding saddle, silk rope, sunrods (3), 8 gp","source":"Master of the Fallen Fortress"},{"name":"Imrijka","cr":1,"xp":400,"race":"half-Orc","gender":"Female","age_category":"Adult","classes":[{"class":"inquisitor","level":1}],"alignment":"NG","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":1,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+5 armor, +1 Dex, +1 shield","hp":10,"hd":"1d8+2","hd_value":1,"fort":3,"ref":1,"will":4,"defensive_abilities":["Orc ferocity"],"speed":[{"type":"land","speed":20}],"melee":"morningstar +3 (1d8+3) or spiked gauntlet +3 (1d4+3)","ranged":"shortbow +1 (1d6+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"judgment","details":"1/day"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"gentle rest Domain Repose"}]}],"spellsknown_caster_level":1,"spellsknown_concentration":3,"spellsknown":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"command"},{"spell":"magic weapon"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"disrupt undead"},{"spell":"guidance"},{"spell":"stabilize"}]}],"strength":16,"dexterity":12,"constitution":13,"intelligence":10,"wisdom":15,"charisma":8,"baseatk":0,"cmb":3,"cmd":14,"feats":[{"feat":"Intimidating Prowess"}],"skills":[{"skill":"Climb","value":-2},{"skill":"Intimidate","value":9},{"skill":"Knowledge (dungeoneering)","value":4},{"skill":"Knowledge (religion)","value":4},{"skill":"Perception","value":6},{"skill":"Sense Motive","value":7},{"skill":"Survival","value":6}],"languages":["Common","Orc"],"sq":["monster lore +2","Orc blood","stern gaze","weapon familiarity"],"special_abilities":[{"type":"Judgment","kind":"Su","details":"You can pronounce judgment upon your foes as a swift action, receiving a bonus or special ability based on the type of judgment made. The bonuses granted by the judgment continue to improve on following rounds, reaching a maximum bonus that lasts until the judgment ends. You can use this ability once per day. Once activated, this ability lasts until the combat ends, at which point all of the bonuses end. You must participate in the combat to gain these bonuses. If you are frightened, panicked, paralyzed, stunned, unconscious, or otherwise prevented from participating in the combat, the ability doesn't end, but all of the bonuses reset to those granted on the first round until you can participate in the combat again. When you use this ability, you must select one type of judgment to make. As a swift action, you can change this judgment to another type, but doing so resets the bonus granted to those granted on the first round. The judgments are as follows. Destruction: You are filled with divine wrath, gaining a +1 sacred bonus on all weapon damage rolls. This bonus increases by +1 each round after the first, to a maximum of +3. Healing: You gain fast healing 1. This causes you to heal 1 point of damage each round as long as you are alive and the judgment lasts. This increases to fast healing 2 on the second round and to fast healing 3 on the third round. Justice: The judgment spurs you to seek justice, granting a +1 sacred bonus on all attack rolls. This bonus increases by +1 each round after the first, to a maximum of +3. Piercing: The judgment grants a +1 sacred bonus on concentration checks and caster level checks made to overcome a target's spell resistance. This bonus increases by +1 each round after the first to a maximum of +3. Protection: You are surrounded by a protective aura, granting a +1 sacred bonus to Armor Class. This bonus increases by +1 each round after the first, to a maximum of +3. Purity: You are protected from the vile taint of your foes, gaining a +1 sacred bonus on all saving throws. This bonus increases by +1 each round after the first, to a maximum of +3. Resiliency: The judgment makes you resistant to harm, granting DR 1/magic. This bonus increases to 2/magic on the second round, and 3/magic on the third and following rounds. Resistance: You gain 2 points of energy resistance against one energy type (acid, cold, electricity, fire, or sonic) chosen when the judgment is declared. The protection increases to 4 on the second round, and to 6 on the third round."},{"type":"Monster Lore","kind":"Ex","details":"When making Knowledge skill checks to identify the abilities and weaknesses of creatures, add your Wisdom modifier as a bonus on the roll."},{"type":"Spells","details":"You cast divine spells drawn from the inquisitor spell list. You can cast any spell you know at any time without preparing it ahead of time, assuming you have not yet used up your allotment of spells per day for the spell's level. The Difficulty Class for a saving throw against your spell is 10 + the spell level + your Wisdom modifier. Domain Your deity (Pharasma, goddess of fate and death) influences your alignment, what magic you can perform, and your values. Although not as tied to the tenets of the deity as a cleric, you must still hold such guidelines in high regard, despite that fact you can go against them if it serves the greater good of the faith. You have one domain (Repose) and gain its domain powers as a cleric."},{"type":"Stern Gaze","kind":"Ex","details":"You are skilled at sensing deception and intimidating your foes. You receive a +1 morale bonus on all Intimidate and Sense Motive checks."}],"gear":"scale mail, light wooden shield, dagger, morningstar, shortbow with 20 arrows, spiked gauntlet, backpack, manacles, rations (4), silver holy symbol, spell component pouch, sunrod, 6 gp, alchemist's fire, holy water","source":"Master of the Fallen Fortress"},{"name":"Alahazra","cr":1,"xp":400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"oracle","level":1}],"alignment":"LG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"senses":["darkvision 30 ft."],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex, +1 dodge","hp":8,"hd":"1d8","hd_value":1,"fort":-1,"ref":2,"will":3,"weaknesses":["oracle's curse (clouded vision)"],"speed":[{"type":"land","speed":30}],"melee":"quarterstaff +0 (1d6) or touch of flame +0 touch (1d6 fire)","ranged":"sling +2 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"touch of flame","details":"6/day, 1d6 fire"}],"spellsknown_caster_level":1,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds"},{"spell":"doom"},{"spell":"magic stone"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"stabilize Mystery Flame"}]}],"strength":10,"dexterity":14,"constitution":8,"intelligence":13,"wisdom":12,"charisma":17,"baseatk":0,"cmb":0,"cmd":13,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Climb","value":3},{"skill":"Diplomacy","value":7},{"skill":"Heal","value":5,"special":"+2 with healer's kit"},{"skill":"Knowledge (history)","value":5},{"skill":"Spellcraft","value":5}],"languages":["Common","Draconic"],"sq":["revelation (touch of flame)"],"special_abilities":[{"type":"Oracle's Curse","kind":"Ex","details":"Each oracle is cursed, but this curse comes with a benefit as well as a hindrance. Your curse cannot be removed or dispelled without the aid of a deity. Clouded Vision: Your eyes are obscured, making it difficult for you to see. You cannot see anything beyond 30 feet, but you can see as if you had darkvision. Revelation At 1st level, you uncover a new secret about the mystery that grants your powers and abilities. Unless otherwise noted, activating the power of a revelation is a standard action. Your revelation is Touch of Flame."},{"type":"Spells","details":"You cast divine spells drawn from the cleric spell lists. You can cast any spell you know without preparing it ahead of time. The Difficulty Class for a saving throw against your spells is 10 + the spell's level + your Charisma modifier. Like other spellcasters, you can cast only a certain number of spells of each spell level per day. Unlike other divine spellcasters, your selection of spells is extremely limited. You also know all cure spells (cure spells include all spells with \"cure\" in their names). Unlike a cleric, you need not prepare your spells in advance. You can cast any spell you know at any time, assuming you have not yet used up your spells per day for that spell level. Mystery Each oracle draws upon a divine mystery to grant her spells and powers. This mystery also grants additional class skills and other special abilities. This mystery can represent a devotion to one ideal, prayers to deities that support the concept, or a natural calling to champion a cause. Regardless of the source, a mystery manifests in a number of ways as the oracle gains levels. Your mystery is Flame."}],"gear":"studded leather armor, quarterstaff, sling with 10 bullets, backpack, fortune-telling bones, healer's kit, rations (6), silver holy symbol, spell component pouch, 10 gp, scrolls of cure light wounds (2), thunderstone","source":"Master of the Fallen Fortress"},{"name":"Balazar","cr":1,"xp":400,"race":"gnome","gender":"Male","age_category":"Adult","classes":[{"class":"summoner","level":1}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["gnome"],"init":1,"senses":["low-light vision"],"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 armor, +1 Dex, +1 size","hp":9,"hd":"1d8+1","hd_value":1,"fort":1,"ref":1,"will":3,"save_mods":"+2 vs. illusions","speed":[{"type":"land","speed":20}],"melee":"club -1 (1d4-2)","ranged":"light crossbow +2 (1d6/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"prestidigitation"}]},{"frequency":"6/day","spells":[{"spell":"summon monster I"}]}],"spellsknown_caster_level":1,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"mage armor"},{"spell":"magic fang"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"read magic"}]}],"strength":6,"dexterity":13,"constitution":12,"intelligence":14,"wisdom":12,"charisma":17,"baseatk":0,"cmb":-3,"cmd":8,"feats":[{"feat":"Spell Focus (conjuration)"}],"skills":[{"skill":"Climb","value":-2},{"skill":"Handle Animal","value":7},{"skill":"Knowledge (arcana)","value":6},{"skill":"Ride","value":5},{"skill":"Spellcraft","value":6},{"skill":"Use Magic Device","value":7}],"languages":["Common","Gnome","Goblin","Orc","Sylvan"],"sq":["defensive training","eidolon","gnome magic","hatred","life link","obsessive","weapon familiarity"],"special_abilities":[{"type":"Life Link","kind":"Su","details":"Your life and your eidolon's are closely bound. Whenever the eidolon takes enough damage to send it back to its home plane, you can, as a free action, sacrifice any number of hit points. Each hit point sacrificed in this way prevents 1 point of damage done to the eidolon. This can prevent the eidolon from being sent back to its home plane. In addition, you and the eidolon must remain within 100 ft. of one another for the eidolon to remain at full strength. If the eidolon is beyond 100 ft. but closer than 1,000 feet, its current and maximum hit point totals are reduced by 50%. Current hit points lost in this way are not restored when the eidolon gets closer to you, but its maximum hit point total does return to normal."},{"type":"Spells","details":"You cast arcane spells drawn from the summoner spell list. You can cast any spell you know without preparing it ahead of time, assuming you have not yet used up your allotment of spells per day for the spell's level. The Difficulty Class for a saving throw against your spell is 10 + the spell level + your Charisma modifier. Eidolon You have the ability to summon to your side a powerful outsider called an eidolon. Eidolons are treated as summoned creatures, except that they are not sent back to their home plane until reduced to a number of negative hit points equal to or greater than their Constitution score. Due to its tie to you, your eidolon can touch and attack creatures warded by effects that prevent contact with summoned creatures. You can summon your eidolon once per day in a ritual that takes 1 minute to perform. The eidolon's hit points are unchanged from the last time it was summoned (unless the eidolon was slain, in which case it returns with half its normal hit points). It remains until dismissed by you (a standard action). If the eidolon is sent back to its home plane due to damage, it cannot be summoned again until the following day. Your eidolon, Padrig, resembles a rooster-headed feathered snake. The eidolon bears a glowing rune that is identical to a rune that appears on your forehead as long as the eidolon is summoned. While this rune can be hidden through mundane means, it cannot be concealed through magic that changes appearance, such as alter self or polymorph (although invisibility does conceal it as long as the spell lasts)."},{"type":"Summon Monster I","kind":"Sp","details":"You have summon monster I as a spell-like ability. Using this ability is a standard action, and the summoned creature remains for 1 minute (instead of 1 round). You cannot have more than one summon monster spell active in this way at one time. If this ability is used again, any existing summon monster spell immediately ends."}],"gear":"leather armor, club, light crossbow with 10 bolts, dagger, backpack, pipe, spell component pouch, signal whistle, sunrods (3), 13 gp, scroll of shield, alchemist's fire","source":"Master of the Fallen Fortress"},{"name":"Feiya","cr":1,"xp":400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"witch","level":1}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":12,"ac_touch":12,"ac_flat_footed":10,"ac_mods":"+2 Dex","hp":8,"hd":"1d6+2","hd_value":1,"fort":1,"ref":4,"will":2,"speed":[{"type":"land","speed":30}],"melee":"quarterstaff -1 (1d6-1) or dagger -1 (1d4-1/19-20)","ranged":"dart +2 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hex","details":"slumber [DC 13]"}],"spellsprepared_caster_level":1,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"mage armor"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"touch of fatigue"}]}],"strength":8,"dexterity":14,"constitution":12,"intelligence":17,"wisdom":10,"charisma":13,"baseatk":0,"cmb":-1,"cmd":11,"feats":[{"feat":"Alertness"},{"feat":"Arcane Strike"},{"feat":"Magical Aptitude"}],"skills":[{"skill":"Climb","value":-1},{"skill":"Heal","value":4,"special":"+2 with healer's kit"},{"skill":"Intimidate","value":5},{"skill":"Knowledge (arcana)","value":7},{"skill":"Knowledge (nature)","value":7},{"skill":"Sense Motive","value":2},{"skill":"Spellcraft","value":9},{"skill":"Use Magic Device","value":7}],"languages":["Common","Aklo","Elven","Sylvan"],"sq":["witch's familiar (fox named Daji; stores all prepared spells, plus cause fear, charm person, identify, obscuring mist, and all 0-level spells)"],"special_abilities":[{"type":"Slumber","kind":"Su","details":": You can cause a creature within 30 ft. to fall into a deep, magical sleep, as per the spell sleep. The creature receives a Will save to negate the effect. If the save fails, the creature falls asleep for 1 round. Unlike sleep, this hex can affect a creature of any HD. The creature will not wake due to noise or light, but others can rouse it with a standard action. This hex ends immediately if the creature takes damage. Whether or not the save is successful, a creature cannot be the target of this hex again for 1 day."},{"type":"Spells","details":"You cast arcane spells drawn from the witch spell list. You must choose and prepare your spells ahead of time. The Difficulty Class for a saving throw against your spell is 10 + the spell level + your Intelligence modifier. You must choose and prepare your spells ahead of time by getting 8 hours of sleep and spending 1 hour communing with your familiar. While communing, you decide which spells to prepare. Hex Witches learn a number of magic tricks, called hexes, that grant them powers or weaken foes. At 1st level, you know one hex (slumber). Using a hex is a standard action that doesn't provoke an attack of opportunity. There is no daily limit to how many times you can use a hex. The save to resist a hex is equal to 10 + 1/2 your level + your Intelligence modifier."},{"type":"Witch's Familiar","kind":"Ex","details":"You have a close bond with a familiar, a creature that teaches you magic and helps to guide you along your path. Your familiar (Daji, a fox) also aids you by granting you a bonus on saving throws and helping with some types of magic. You must commune with your familiar each day to prepare your spells (just as a wizard studies a spellbook to prepare his spells). Your familiar stores all of the spells that you know, and you cannot prepare a spell that isn't stored by your familiar. If a familiar is lost or dies, it can be replaced 1 day later through a special ritual that costs 500 gp per witch level. The ritual takes 8 hours to complete. Fox familiar: You gain a +2 bonus on Reflex saves."}],"gear":"dagger, darts (6), quarterstaff, backpack, fetishes, healer's kit, iron pot, rations (4), spell component pouch, sunrods (2), 1 gp, tanglefoot bag","source":"Master of the Fallen Fortress"},{"name":"Baroness Pavetta Stroon-Drelev","cr":6,"xp":2400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":8}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":10,"ac_touch":10,"ac_flat_footed":10,"hp":36,"hd":"8d8","hd_value":8,"fort":2,"ref":2,"will":9,"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +6 (1d4-1/19-20)","ranged":"thrown object +6 (1d4-1)","space":"5 ft.","reach":"5 ft.","strength":8,"dexterity":10,"constitution":10,"intelligence":12,"wisdom":12,"charisma":15,"baseatk":6,"cmb":5,"cmd":15,"feats":[{"feat":"Alertness"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Skill Focus (Intimidate)"},{"feat":"Throw Anything"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":15},{"skill":"Intimidate","value":18},{"skill":"Knowledge (nobility)","value":12},{"skill":"Perception","value":14},{"skill":"Perform (Dance)","value":13},{"skill":"Sense Motive","value":14}],"languages":["Common","Skald"],"gear":"masterwork dagger, stone of alarm, diamond crown worth 1,500 gp, diamond necklace worth 500 gp, emerald ring worth 250 gp, Jewel (annoying dog; treat as a cat with no claw attacks), royal outfit worth 300 gp, sapphire earrings worth 400 gp, signet ring worth 300 gp","during_combat":"Baroness Pavetta views physical combat as a job for paid underlings, but if any handy objects like vases, small sculptures, or serving trays lie nearby, she uses her Throw Anything feat to attack from range.","morale":"Baroness Pavetta surrenders to any legitimate show of force.","source":"AP 34"},{"name":"Beshtu","cr":11,"xp":12800,"race":"hill giant","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":4}],"alignment":"NE","size":"Large","type":"humanoid","sub_types":["giant"],"init":0,"senses":["low-light vision"],"ac":23,"ac_touch":9,"ac_flat_footed":23,"ac_mods":"+10 armor, +4 natural, -1 size","hp":165,"hd":"10d8+4d10+98","hd_value":14,"fort":18,"ref":4,"will":10,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","rock catching"],"speed":[{"type":"land","speed":30}],"melee":"Large +1 giant-bane greatsword +21 (3d6+16/19-20)","ranged":"rock +10 (1d8+13/19-20)","space":"10 ft.","reach":"10 ft.","strength":29,"dexterity":10,"constitution":24,"intelligence":8,"wisdom":10,"charisma":5,"baseatk":11,"cmb":21,"cmd":31,"feats":[{"feat":"Bleeding Critical"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Lunge"},{"feat":"Mounted Combat"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Climb","value":9},{"skill":"Fly","value":0},{"skill":"Intimidate","value":14},{"skill":"Perception","value":8},{"skill":"Ride","value":6}],"sq":["armor training 1"],"gear":"Large +1 full plate, Large +1 giant-bane greatsword, 248 gp, potion of cure serious wounds","during_combat":"Beshtu remains mounted, attacking foes as her dinosaur tramples as many as it can each round.","source":"Curse of the Riven Sky, Pathfinder RPG Bestiary 150"},{"name":"Zoarth","cr":14,"xp":38400,"race":"cloud giant","gender":"Male","age_category":"Adult","classes":[{"class":"evoker","level":6}],"alignment":"NE","size":"Huge","type":"humanoid","sub_types":["giant"],"init":7,"senses":["low-light vision","scent"],"ac":31,"ac_touch":11,"ac_flat_footed":28,"ac_mods":"+4 mage armor, +3 Dex, +12 natural, +4 shield, -2 size","hp":247,"hd":"16d8+6d6+154","hd_value":22,"fort":19,"ref":10,"will":16,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":50}],"melee":"2 slams +25 (2d6+12)","ranged":"rock +16 (2d6/19-20)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"intense spells +3 damage"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"levitate","details":"000 lbs., self plus 2"},{"spell":"obscuring mist 1/"}]},{"frequency":"7/day","spells":[{"spell":"force missile","details":"1d4+3"}]}],"spellsprepared_caster":"evoker","spellsprepared_caster_level":6,"spellsprepared_concentration":10,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"fireball"},{"spell":"fly"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":3,"spells":[{"spell":"glitterdust"},{"spell":"scorching ray"},{"spell":"web"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"open/close"}]}],"prohibited_schools":"Enchantment, Illusion","strength":35,"dexterity":17,"constitution":25,"intelligence":18,"wisdom":18,"charisma":10,"baseatk":15,"cmb":29,"cmd":42,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Craft Wand"},{"feat":"Great Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Greater Overrun"},{"feat":"Improved Bull Rush"},{"feat":"Improved Iron Will"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Scribe Scroll"}],"skills":[{"skill":"Climb","value":20},{"skill":"Craft (carpentry)","value":17},{"skill":"Craft (stonemasonry)","value":17},{"skill":"Diplomacy","value":9},{"skill":"Fly","value":0},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":17},{"skill":"Knowledge (engineering)","value":12},{"skill":"Knowledge (geography)","value":12},{"skill":"Knowledge (history)","value":17},{"skill":"Knowledge (nobility)","value":12},{"skill":"Linguistics","value":17},{"skill":"Perception","value":17},{"skill":"Perform (string)","value":8},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":17},{"skill":"Use Magic Device","value":10}],"languages":["Common","Celestial","Giant","Infernal"],"sq":["arcane bond (ring)","oversized weapon"],"gear":"headband of vast intelligence +2, scroll of dimension door, scroll of fireball, scroll of fly, wand of lightning bolt (6d6, DC 14, 34 charges)","before_combat":"Zoarth has already cast mage armor and shield on himself.","during_combat":"Zoarth casts fireball and slow, and then scorching ray and magic missile, only using his wand of lightning bolt once those spells are exhausted.","morale":"If reduced to fewer than 85 hit points, Zoarth uses his scroll of dimension door to escape to elsewhere in the castle.","base_statistics":"Zoarth's AC without spells is 23, touch 11, flatfooted 20.","source":"Curse of the Riven Sky"},{"name":"Jurn Enforcer","cr":10,"xp":9600,"race":"hill giant","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":3}],"alignment":"NE","size":"Large","type":"humanoid","sub_types":["giant"],"init":5,"senses":["low-light vision"],"ac":26,"ac_touch":10,"ac_flat_footed":25,"ac_mods":"+7 armor, +1 Dex, +9 natural, -1 size","hp":129,"hd":"10d8+3d10+68","hd_value":13,"fort":15,"ref":5,"will":6,"save_mods":"+1 vs. fear","defensive_abilities":["rock catching bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"Large mwk greataxe +19 (3d6+12/x3) or 2 slams +17 (1d8+8)","ranged":"rock +11 (1d8+8/19-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"create elemental"}],"strength":26,"dexterity":12,"constitution":20,"intelligence":8,"wisdom":11,"charisma":5,"baseatk":10,"cmb":19,"cmd":30,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Improved Initiative"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (greataxe)"},{"feat":"Weapon Focus (rock)"}],"skills":[{"skill":"Climb","value":9},{"skill":"Fly","value":0},{"skill":"Intimidate","value":13},{"skill":"Perception","value":9},{"skill":"Stealth","value":0}],"languages":["Giant"],"sq":["armor training 1"],"special_abilities":[{"type":"Create Elemental","kind":"Su","details":"As a swift action, as part of throwing a rock, an enforcer can transform a hurled rock into a Medium earth elemental. If the giant hits a target with its rock, the stone transforms into an elemental, suddenly sprouting arms and automatically attempting to grapple the target on the giant's turn. If the rock misses, it lands 1d6x5 ft. away in a random direction and transforms into an elemental; the elemental isn't prone and immediately charges into battle."}],"gear":"Large masterwork banded mail, Large masterwork greataxe, 99 gp","during_combat":"The enforcers really enjoy using their ability to create earth elementals, and they use it before entering melee if possible.","source":"Curse of the Riven Sky"},{"name":"Pitax Herald","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"bard","level":6}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+5 armor, +2 Dex","hp":45,"hd":"6d8+18","hd_value":6,"fort":3,"ref":7,"will":5,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic","speed":[{"type":"land","speed":30}],"melee":"mwk rapier +7 (1d6/18-20)","ranged":"+1 shortbow +7 (1d6+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance","details":"7 rounds/day, standard action, countersong, distraction, fascinate, inspire competence +2, inspire courage +2, suggestion"}],"spellsknown_caster_level":6,"spellsknown_concentration":9,"spellsknown":[{"spell_level":2,"spell_slots":4,"spells":[{"spell":"animal messenger"},{"spell":"detect thoughts"},{"spell":"enthrall"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"cure light wounds"},{"spell":"silent image"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"light"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"summon instrument"}]}],"strength":10,"dexterity":14,"constitution":13,"intelligence":12,"wisdom":10,"charisma":16,"baseatk":4,"cmb":4,"cmd":16,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":12},{"skill":"Intimidate","value":12},{"skill":"Knowledge (local)","value":13},{"skill":"Perception","value":9},{"skill":"Perform (Oratory)","value":12},{"skill":"Perform (Wind)","value":12},{"skill":"Stealth","value":10}],"languages":["Common","Halit"],"sq":["bardic knowledge +3","lore master 1/day","versatile performance (oratory, wind)","well-versed"],"gear":"+1 chain shirt, +1 shortbow with 20 arrows, masterwork rapier, potion of invisibility, potion of fly","source":"AP 35"},{"name":"Pitax Warden","cr":5,"xp":1600,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":6}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":20,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+10 armor","hp":51,"hd":"6d10+18","hd_value":6,"fort":9,"ref":2,"will":3,"save_mods":"+2 vs. fear","speed":[{"type":"land","speed":20}],"melee":"+1 greatsword +13 (2d6+8/19-20)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":10,"constitution":14,"intelligence":8,"wisdom":12,"charisma":13,"baseatk":6,"cmb":10,"cmd":20,"feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Power Attack"},{"feat":"Skill Focus (Ride)"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Intimidate","value":10},{"skill":"Perception","value":7},{"skill":"Ride","value":8}],"languages":["Common"],"sq":["armor training +1","bravery +2","weapon training (heavy blades +1)"],"gear":"+1 full plate, +1 greatsword, potions of cure moderate wounds (2)","source":"AP 35"},{"name":"Villamor Koth","cr":14,"xp":38400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":15}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":26,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+9 armor, +2 deflection, +1 Dex, +1 dodge, +5 natural, -2 rage","hp":217,"hd":"15d12+120","hd_value":15,"fort":15,"ref":6,"will":11,"defensive_abilities":["improved uncanny dodge","indomitable will","trap sense +5"],"dr":"5/-","speed":[{"type":"land","speed":40}],"melee":"+1 vicious greataxe +24 (1d12+11/19-20/x3 plus 2d6) or mwk lance +24 (1d8+10/x3)","ranged":"mwk longbow +17 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"greater rage","details":"35 rounds/day"},{"type":"rage powers","details":"guarded stance [+3 + Con bonus], knockback, no escape, rolling dodge +3, unexpected strike"}],"strength":24,"dexterity":13,"constitution":22,"intelligence":8,"wisdom":12,"charisma":10,"baseatk":15,"cmb":22,"cmd":34,"feats":[{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Critical (greataxe)"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greataxe)"}],"skills":[{"skill":"Intimidate","value":18},{"skill":"Knowledge (nature)","value":13},{"skill":"Linguistics","value":0},{"skill":"Perception","value":14},{"skill":"Ride","value":15},{"skill":"Survival","value":14}],"languages":["Common","Halit"],"sq":["fast movement"],"gear":"+5 hide armor, +1 vicious greataxe, ring of protection +2, potions of barkskin +5 (3)","before_combat":"Before any fight, Villamor drinks a potion of barkskin.","during_combat":"Villamor takes his time jousting and is eager to toy with the PCs in an attempt to humiliate and hurt them-especially if they're doing well in the competition and look like they have a good chance at winning. He figures that if he can egg their jousting contestant into attacking him, he can kill that PC in self-defense without getting in too much trouble. He doesn't attempt to unseat a PC contestant, but instead makes actual attacks against his opponent with his lance on each pass. Note that each time a character takes damage while riding, she must make a DC 5 Ride check to remain in the saddle-it's certainly possible this tactic could unseat a particularly inept rider. To observers, of course, Villamor's tactics are easily mistaken for overly aggressive attempts to unseat a rider-the crowd certainly loves the violence. If he's properly unseated by a PC, Villamor swallows his pride for now and nurtures the thought of revenge-he's one of Irovetti's closest allies, after all, and knows that the king plans to go to war.","morale":"Villamor doesn't fight to the death at this time; if the PCs respond to his goading by attacking, he'll \"defend\" himself (and attempt to kill the attacking PC), but if all the PCs start to gang up on him, or if he's reduced to fewer than 150 hit points, he breaks off his attack and Irovetti steps in to try to calm things down. If the PCs continue to attack, Irovetti uses dimension door to escape back to the Royal Pavilion with Villamor and announces that the Rushlight Festival is cancelled due to unwarranted aggression on a visitor's behalf. He gives the PCs an hour to leave Pitax before he attempts to have them arrested as criminals; in any event, this development gives him a handy, if flimsy, excuse to go to war with the PCs. Certainly the PCs aren't thought of kindly by the other competitors and attendants at the festival, for they see the PCs as the ones responsible for the tournament's cancellation in this case. See Part Two for more information on how the war develops.","source":"AP 35"},{"name":"Minognos-Ushad","cr":14,"xp":38400,"race":"wyvern","gender":"Female","age_category":"Old","alignment":"NE","size":"Huge","type":"dragon","init":-2,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":22,"ac_touch":6,"ac_flat_footed":22,"ac_mods":"-2 Dex, +16 natural, -2 size","hp":225,"hd":"18d12+108","hd_value":18,"fort":16,"ref":9,"will":13,"immunities":["paralysis","sleep"],"speed":[{"type":"fly","speed":60,"maneuverability":"poor"},{"type":"land","speed":20}],"melee":"sting +24 (2d6+8 plus poison), bite +24 (4d6+8/19-20), 2 wings +19 (2d6+4)","space":"5 ft.","reach":"15 ft.","special_attacks":[{"type":"poison","details":"save DC 24; frequency 1/round for 6 rounds; effect 1d4 Con; cure 2 consecutive saves"},{"type":"rake","details":"2 talons +24, 1d8+8"}],"strength":26,"dexterity":7,"constitution":20,"intelligence":9,"wisdom":14,"charisma":11,"baseatk":18,"cmb":28,"cmd":36,"feats":[{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Natural Attack (bite, sting, wing)"},{"feat":"Staggering Critical"},{"feat":"Toughness"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":11},{"skill":"Intimidate","value":21},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":23},{"skill":"Stealth","value":11}],"languages":["Draconic"],"during_combat":"Minognos-Ushad swoops into an attack using a Vital Strike sting on the first round of combat, then makes full attacks at the strongest-looking foe in following rounds.","morale":"Minognos-Ushad flees combat if brought below 50 hit points, abandoning her lair and flying up into the mountains to nurse her wounds upon the peak of Mount Branthlend. Once she heals, she returns to seek out those who drove her from her lair for revenge.","source":"AP 35, Pathfinder RPG Bestiary 282"}];
